    unsigned b865 = stwo_m31_sub(b864, b746);
    unsigned b1130 = stwo_m31_sub(b1129, b865);
    unsigned b43 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 1u, 123u, row_index, 0);
    unsigned b116 = stwo_trace_value(trace_cols, interaction_offsets, row_count, log_n_rows, 1u, 285u, row_index, 0);
    unsigned b359 = stwo_m31_add(b43, b116);
    unsigned b1144 = stwo_m31_sub(b1130, b359);
    unsigned b1202 = stwo_m31_mul(b1201, b1144);
    unsigned b1203 = stwo_m31_sub(b1200, b1202);
    unsigned b1230 = stwo_m31_add(b1203, b123);
    unsigned b1231 = stwo_m31_sub(b1229, b1230);
    StwoCudaQm31 e8 = StwoCudaQm31{ b1231, b125, b125, b125 };
    acc = stwo_qm31_add(acc, stwo_qm31_mul(e8, stwo_load_qm31(random_coeff_powers, rc_base + 8u)));

    // Fused denom_inv multiply + in-place accumulator update.
    unsigned denom_idx = row_index >> log_n_rows;
    StwoCudaQm31 result = stwo_qm31_mul_base(acc, denom_inv[denom_idx]);
    coord_0[row_index] = stwo_m31_add(coord_0[row_index], result.a);
    coord_1[row_index] = stwo_m31_add(coord_1[row_index], result.b);
    coord_2[row_index] = stwo_m31_add(coord_2[row_index], result.c);
    coord_3[row_index] = stwo_m31_add(coord_3[row_index], result.d);
}
